from copy import deepcopy
from pathlib import Path

from ..qc.config import Config
from ..utils.logger import logger


class QCMatcher:

    def __init__(self, collector, environment):
        self._collector = collector
        self._env = environment
        self._qc_config_path, self._path_source = self._choose_qc_config_path()
        self._data = collector.result

    def match_configs(self):
        """Match QC configuration for given test cases list"""
        if self._env.no_qc:
            return
        configs_list = self._search_for_configs()
        if not configs_list:
            logger.warning(
                "Failed to find proper QC file. Skipping QC config matching."
            )
            return
        for suite in self._collector.result:
            self._match_qc_for_suite(suite, configs_list)

    def _choose_qc_config_path(self):
        if self._collector.dynamic_qc_file_path:
            return self._collector.dynamic_qc_file_path, "Keyword"
        elif self._env.qc_config_path:
            return self._env.qc_config_path, "Command line"
        elif self._collector.suite_source:
            return (
                Path(self._collector.suite_source).with_suffix(".qc").as_posix(),
                "Generated by suite name",
            )
        else:
            return None, "No qc path has been assigned"

    def _search_for_configs(self):
        if Path(self._qc_config_path).exists() and Path(self._qc_config_path).is_file():
            logger.info(
                f"Looking for QC configuration in file: {self._qc_config_path}"
            )
            return [self._qc_config_path]
        suite_dir_path = Path(self._collector.suite_source).parent.as_posix()
        logger.warning(
            "No command line (-qc parameter) file, dynamic file from keyword or suite_name.qc file found."
        )
        logger.info("Looking for QC configuration in the whole test suite directory")
        try:
            return [
                path.as_posix()
                for path in Path(suite_dir_path).iterdir()
                if path.suffix == ".qc"
            ]
        except Exception:
            return []

    def _match_qc_for_suite(self, suite, configs_list):
        qc_matched = False
        for config_path in configs_list:
            logger.debug(f"Checking for config in: {config_path}")
            matched_test_data = []
            for test in suite["test_cases"]:
                test_qc_config, qc_matched = self._get_qc_config_items(
                    test, config_path
                )
                if not test["multi_qc"]:
                    test_qc_config = test_qc_config[:1]
                test_entries = self._generate_qc_entries(test, test_qc_config)
                matched_test_data.extend(test_entries)
            if qc_matched:
                logger.info(f"Config matched for: {config_path}")
                suite["test_cases"] = matched_test_data
                break

    def _get_qc_config_items(self, test, config_path):
        if not Path(config_path).exists():
            return [{"qc_path": "", "qc_test_set": ""}], False
        with open(config_path) as f:
            cfg = Config(f.read())
            cfg.validate()
            test_name = test["qc_test_instance_name"] or test["name"]
            return cfg.get_qc(
                test["build"], test_name, self._env.label, test["suite_path"]
            )

    def _generate_qc_entries(self, test, test_qc_config):
        matched_entries = []
        for config_entry in test_qc_config:
            entry = deepcopy(test)
            entry["qc_test_instance_name"] = (
                entry["qc_test_instance_name"] or entry["name"]
            )
            entry["qc_testlab_path"] = config_entry["qc_path"]
            entry["qc_test_set_name"] = config_entry["qc_test_set"]
            entry["qc_domain"] = entry["qc_domain"] or config_entry["qc_domain"]
            entry["qc_project"] = entry["qc_project"] or config_entry["qc_project"]
            matched_entries.append(entry)
        return matched_entries
